const config = $('Get Client Config').item.json;
const rows = $input.all().map(i => i.json);
const completed = rows.filter(r => String(r.status || '').trim() === 'Complete');

const results = [];
for (const r of completed) {
  const payload = {
    jobId: r.jobId,
    customerId: r.customerId,
    customerName: r.customerName,
    customerEmail: r.customerEmail || undefined,
    customerPhone: r.customerPhone || undefined,
    jobDescription: r.jobDescription,
    jobValue: Number(r.jobValue),
    milestoneNumber: r.milestoneNumber || null,
    milestoneLabel: r.milestoneLabel || null,
  };

  let status, invoiceReference, invoiceNumber, errorMessage;
  try {
    const res = await fetch('https://keystoneconsultancy.app.n8n.cloud/webhook/invoice/job-completed', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const body = await res.json();
    if (body.status === 'success') {
      status = 'Invoiced';
      invoiceReference = body.invoiceReference || '';
      invoiceNumber = body.invoiceNumber || '';
      errorMessage = '';
    } else if (body.status === 'skipped') {
      status = 'Skipped - Duplicate';
      invoiceReference = body.invoiceReference || '';
      invoiceNumber = '';
      errorMessage = '';
    } else if (body.status === 'rejected') {
      status = 'Error - Rejected';
      invoiceReference = '';
      invoiceNumber = '';
      errorMessage = (body.errors || []).join(', ');
    } else {
      status = 'Error - Unexpected Response';
      invoiceReference = '';
      invoiceNumber = '';
      errorMessage = JSON.stringify(body).slice(0, 500);
    }
  } catch (err) {
    status = 'Error - Request Failed';
    invoiceReference = '';
    invoiceNumber = '';
    errorMessage = String((err && err.message) || err).slice(0, 500);
  }

  results.push({
    json: {
      row_number: r.row_number,
      status,
      invoiceReference,
      invoiceNumber,
      processedAt: new Date().toISOString(),
      errorMessage,
      jobsSheetId: config.jobsSheetId,
      jobsSheetTabName: config.jobsSheetTabName,
    }
  });
}

return results;
